                     style="object-fit:cover"
                     @onerror="this.src='https://via.placeholder.com/100'" />
                @* Show avatar URL below preview *@
                <small class="d-block text-muted text-truncate" style="max-width:160px;margin:0 auto">@_profileAvatarUrl</small>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input class="form-control" @bind="_profileDisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_profileEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Avatar URL</label>
                    <input class="form-control" @bind="_profileAvatarUrl" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="3" @bind="_profileBio"></textarea>
                </div>

                <button class="btn btn-primary me-2" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };
}

@* ─────────────────────────── Notifications ─────────────────────────── *@
@{
    RenderFragment RenderNotifications() => __builder =>
    {
        <h4 class="mb-3">Notifications</h4>

        <div class="mb-3 form-check form-switch">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="mb-3 form-check form-switch">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="mb-3 form-check form-switch">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>

        <h6 class="mt-4">Muted Channels</h6>
        <div class="list-group mb-3">
            @foreach (var channel in MockSettingsService.AllChannels)
            {
                var ch = channel;
                <label class="list-group-item d-flex align-items-center">
                    <input class="form-check-input me-2" type="checkbox"
                           checked="@_mutedChannels.Contains(ch)"
                           @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                    <span>#@ch</span>
                </label>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveNotificationPrefs" disabled="@_saving">
            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Preferences
        </button>
    };
}

@* ─────────────────────────── Security ─────────────────────────── *@
@{
    RenderFragment RenderSecurity() => __builder =>
    {
        <h4 class="mb-3">Security</h4>

        @* ── Change Password expandable panel ── *@
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor:pointer" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
            </div>
            @if (_passwordPanelOpen)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-warning" @onclick="ChangePassword" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Update Password
                    </button>
                </div>
            }
        </div>

        @* ── Two-factor authentication ── *@
        <div class="d-flex align-items-center mb-4">
            <div class="form-check form-switch me-3">
                <input class="form-check-input" type="checkbox" id="twoFactor" checked="@_twoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
            </div>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="text-muted small mb-4">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        @* ── Active sessions table ── *@
        <h6>Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatRelativeTime(session.LastActive)</td>
                            <td>
                                @if (session.Id != _sessions.FirstOrDefault()?.Id)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => ConfirmRevokeSession(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @* ── Revoke confirmation dialog ── *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background:rgba(0,0,0,.5)">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="() => _sessionToRevoke = null"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                            <button class="btn btn-danger" @onclick="RevokeSession" disabled="@_saving">
                                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                Revoke
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        }
    };
}

@* ─────────────────────────── Appearance ─────────────────────────── *@
@{
    RenderFragment RenderAppearance() => __builder =>
    {
        <h4 class="mb-3">Appearance</h4>

        <div class="row">
            <div class="col-md-6">
                @* Theme *@
                <div class="mb-4">
                    <label class="form-label fw-bold">Theme</label>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="theme-@t" value="@t"
                                   checked="@(_theme == t)"
                                   @onchange="() => _theme = t" />
                            <label class="form-check-label" for="theme-@t">@t</label>
                        </div>
                    }
                </div>

                @* Font size *@
                <div class="mb-4">
                    <label class="form-label fw-bold">Font Size</label>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="fs-@s" value="@s"
                                   checked="@(_fontSize == s)"
                                   @onchange="() => _fontSize = s" />
                            <label class="form-check-label" for="fs-@s">@s</label>
                        </div>
                    }
                </div>

                @* Language *@
                <div class="mb-4">
                    <label class="form-label fw-bold">Language</label>
                    <select class="form-select" @bind="_language">
                        <option>English</option>
                        <option>Spanish</option>
                        <option>French</option>
                        <option>German</option>
                        <option>Japanese</option>
                        <option>Portuguese</option>
                    </select>
                </div>

                @* Compact mode *@
                <div class="mb-4 form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>

            @* ── Live preview ── *@
            <div class="col-md-6">
                <label class="form-label fw-bold">Live Preview</label>
                <div class="border rounded @(_compactMode ? "p-2" : "p-4")"
                     style="@GetPreviewStyle()">
                    <h5 style="font-size:@GetPreviewHeadingSize()">Dashboard</h5>
                    <p style="font-size:@GetPreviewBodySize()" class="@(_compactMode ? "mb-1" : "")">
                        Welcome back! You have <strong>3 new notifications</strong>.
                    </p>
                    <div class="d-flex gap-2 @(_compactMode ? "mt-1" : "mt-3")">
                        <span class="badge bg-primary" style="font-size:@GetPreviewBadgeSize()">Messages</span>
                        <span class="badge bg-success" style="font-size:@GetPreviewBadgeSize()">Tasks</span>
                        <span class="badge bg-warning text-dark" style="font-size:@GetPreviewBadgeSize()">Alerts</span>
                    </div>
                    <hr />
                    <small style="font-size:@GetPreviewSmallSize()" class="text-muted">
                        Theme: @_theme · Font: @_fontSize · Language: @_language · Compact: @(_compactMode ? "On" : "Off")
                    </small>
                </div>
            </div>
        </div>
    };
}

@code {
    // ── General state ──
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private string _toastCss = "alert-success";
    private string _activeSection = "Profile";
    private static readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];

    // ── Profile state ──
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // ── Notification state ──
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];

    // ── Security state ──
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    // ──────────── Lifecycle ────────────

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = profileTask.Result;
        ApplyProfile(_savedProfile);

        // Notifications
        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        // Security
        var sec = securityTask.Result;
        _twoFactorEnabled = sec.TwoFactorEnabled;
        _lastPasswordChange = sec.LastPasswordChange;
        _sessions = sec.Sessions;

        // Appearance
        var app = appearanceTask.Result;
        _theme = app.Theme;
        _fontSize = app.FontSize;
        _language = app.Language;
        _compactMode = app.CompactMode;

        _loading = false;
    }

    // ──────────── Profile helpers ────────────

    private void ApplyProfile(UserProfile p)
    {
        _profileDisplayName = p.DisplayName;
        _profileEmail = p.Email;
        _profileAvatarUrl = p.AvatarUrl;
        _profileBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully.", success: true);
        _saving = false;
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.", success: true);
        }
    }

    // ──────────── Notifications helpers ────────────

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved.", success: true);
        _saving = false;
    }

    // ──────────── Security helpers ────────────

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", success: false);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", success: false);
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _lastPasswordChange = DateTime.UtcNow;
        _currentPassword = _newPassword = _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("Password updated successfully.", success: true);
        _saving = false;
    }

    private void ConfirmRevokeSession(ActiveSession session) => _sessionToRevoke = session;

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions = _sessions.Where(s => s.Id != _sessionToRevoke.Id).ToList();
        _sessionToRevoke = null;
        ShowToast("Session revoked.", success: true);
        _saving = false;
    }

    // ──────────── Appearance helpers ────────────

    private async Task SaveAppearance()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        ShowToast("Appearance settings saved.", success: true);
        _saving = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch { "Dark" => "background:#1e1e2e;color:#cdd6f4;", "System" => "background:#f0f0f5;color:#333;", _ => "background:#fff;color:#212529;" };
        return bg;
    }

    private string GetPreviewHeadingSize() => _fontSize switch { "Small" => "1rem", "Large" => "1.6rem", _ => "1.25rem" };
    private string GetPreviewBodySize() => _fontSize switch { "Small" => "0.8rem", "Large" => "1.15rem", _ => "0.95rem" };
    private string GetPreviewBadgeSize() => _fontSize switch { "Small" => "0.65rem", "Large" => "0.9rem", _ => "0.75rem" };
    private string GetPreviewSmallSize() => _fontSize switch { "Small" => "0.65rem", "Large" => "0.85rem", _ => "0.75rem" };

    // ──────────── Toast ────────────

    private void ShowToast(string message, bool success)
    {
        _toastMessage = message;
        _toastCss = success ? "alert-success" : "alert-danger";
    }

    private static string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

